messages.handler:
return (env) => {
  const typeMap = { single: '单选题', multiple: '多选题', judgement: '判断题', completion: '填空题' };
  const t = typeMap[env.type] || '未知题型';
  return [
    { role: 'system', content: '你是严谨的答题助手。只输出最终答案，不要解释或推理。单选题只输出选项字母（如 A）；多选题输出字母并用 # 连接（如 A#B）；判断题输出 正确 或 错误；填空题直接输出填空内容。' },
    { role: 'user', content: '题型：' + t + '\n题目：' + (env.title || '') + '\n选项：' + (env.options || '无') }
  ];
}

handler:
return (res) => {
  const choice = res && res.choices && res.choices[0];
  const content = choice && choice.message && choice.message.content;
  if (!content) return undefined;
  let answer = String(content).trim();
  answer = answer.replace(/^```[\w-]*\s*/, '').replace(/```$/, '').trim();
  answer = answer.replace(/^(?:答案|answer)\s*[:：]\s*/i, '').trim();
  const letters = answer.toUpperCase();
  if (/^[A-Z](?:[#,，、\s]+[A-Z])+$/.test(letters)) {
    answer = letters.replace(/[#,，、\s]+/g, '#').replace(/#+/g, '#').replace(/^#|#$/g, '');
  }
  return [undefined, answer];
}
